def b64(n):
    chr64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    
    if n == 0:
        return chr64[0]
    
    s = ''
    sgn = '-' if n < 0 else ""
    
    n = abs(n)
    while n > 0:
        s = chr64[n % 64] + s
        n = n // 64
    
    return sgn + s


